import{_ as a,c as t,o as h,ah as o}from"./chunks/framework.CdwlI3v5.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"_layout":"writeup","ctf":"HSCTF 6","chal":"I Thought Trig Was Really Easy","flag":"hsctf{:hyperthonk:}","points":370,"category":"reverse"},"headers":[],"relativePath":"writeups/2019/hsctf/I Thought Trig Was Really Easy/2019-06-03-I Thought Trig Was Really Easy.md","filePath":"writeups/2019/hsctf/I Thought Trig Was Really Easy/2019-06-03-I Thought Trig Was Really Easy.md"}'),s={name:"writeups/2019/hsctf/I Thought Trig Was Really Easy/2019-06-03-I Thought Trig Was Really Easy.md"};function r(i,e,l,n,c,d){return h(),t("div",null,[...e[0]||(e[0]=[o('<blockquote><p>After finishing a hard lesson in geometry class, Keith decided that he wanted to put your understanding of trig and python to the test. Can you solve his challenge?</p></blockquote><blockquote><p><a href="./trig_is_really_hard.py">trig_is_really_hard.py</a></p></blockquote><p>We are given <a href="./trig_is_really_hard.py">trig_is_really_hard.py</a>, which is basically a custom hashing algorithm.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to “Details”">​</a></h2><p>This hashing algorithm output depend on the length on the input, more specifically, <code>2+3+...+(n+1)=n(n+3)/2</code></p><p>The program &#39;hashes&#39; our input, then compare with a preexisting hash.</p><p>Playing around with this, we notice that any changes to the plaintext will only affect the characters afterwards, so all the digits that have been generate remain untouched.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to “Solution”">​</a></h2><p>The length of the hash is <code>90</code>, thus the length of our solution is either <code>-15</code> or <code>12</code>. <code>-15</code> seems a bit hard to achieve so we&#39;ll assume <code>n=12</code></p><p>Now we simply bruteforce each character, ensuring that the length remains at 12 and start matching more and more of the given hash.</p>',10)])])}const u=a(s,[["render",r]]);export{g as __pageData,u as default};
